"""Stage 5: grade the port against the old transaction.

Every case goes through the old screen (the oracle, run fresh) and through the new service (the port's driver),
each starting from the same data. Then the error messages and every table row are compared.

    python3 factory/grade.py ZCRED CASES.json [--out report.json]      cases of your own
    python3 factory/grade.py ZCRED --sealed [--out report.json]         the sealed cases (factory only)

The driver is runs/<TCODE>/port/driver.py with a function run(client, steps). It gets an odata.Client for the new
service (runs/<TCODE>/port/service.json names the service root) and the steps of one case, and does what a user of
the new app would do to achieve the same. It returns nothing; the grader reads the messages from the client's calls
and the rows from the database.
"""
import hashlib
import importlib.util
import json
import os
import sys
import time

sys.path.insert(0, os.path.dirname(__file__))
import abap  # noqa: E402
import odata  # noqa: E402
import oracle  # noqa: E402
import sap  # noqa: E402

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
VOLATILE_ROLLS = {"TIMESTAMP", "TIMESTAMPL", "TZNTSTMPS", "TZNTSTMPL", "SYUZEIT", "UZEIT"}
STOPPED = ("00", "344")  # batch input: the steps ran out on a screen, so the user stopped there


def load_json(path):
    with open(path) as f:
        return json.load(f)


def volatile_fields(tcode):
    d = load_json(os.path.join(ROOT, "runs", tcode, "extract", "dictionary.json"))
    out = {}
    for table, t in d["tables"].items():
        out[table] = {f["FIELDNAME"] for f in t["fields"]
                      if f["ROLLNAME"] in VOLATILE_ROLLS or f["DATATYPE"] == "TIMS"}
    return out


def table_fields(tcode):
    d = load_json(os.path.join(ROOT, "runs", tcode, "extract", "dictionary.json"))
    return {t: [f["FIELDNAME"] for f in v["fields"] if not f["FIELDNAME"].startswith(".")] for t, v in
            d["tables"].items()}


def read_tables(s, fields):
    return {t: s.sql(f"SELECT {', '.join(fl)} FROM {t}") for t, fl in fields.items()}


def lit(v):
    return "'" + str(v).replace("'", "''") + "'"


def restore_report(baseline, fields):
    lines = []
    for table, rows in baseline.items():
        lines.append(f"DATA lt_{table.lower()} TYPE STANDARD TABLE OF {table.lower()}.")
        for r in rows:
            assigns = " ".join(f"{f.lower()} = {lit(r[f])}" for f in fields[table] if f != "MANDT" and r[f] != "")
            lines.append(f"APPEND VALUE {table.lower()}( {assigns} ) TO lt_{table.lower()}.")
        lines.append(f"DELETE FROM {table.lower()}.")
        lines.append(f"INSERT {table.lower()} FROM TABLE lt_{table.lower()}.")
    lines.append("COMMIT WORK AND WAIT.")
    lines.append("PERFORM out USING 'DONE' `{}`.")
    return "\n".join(lines)


def norm(value):
    """Compare numbers as numbers: the oracle writes 7000.00 as 7000.0, the database as '7000.00'."""
    if isinstance(value, (int, float)):
        return repr(float(value))
    text = str(value).strip()
    try:
        if text and any(c.isdigit() for c in text) and text.replace(".", "", 1).replace("-", "", 1).isdigit():
            return repr(float(text))
    except ValueError:
        pass
    return text


def normalise_rows(rows, volatile):
    out = []
    for r in rows:
        row = {}
        for k, v in r.items():
            if k == "MANDT":
                continue
            row[k] = ("<set>" if norm(v) not in ("", "0.0") else "<empty>") if k in volatile else norm(v)
        out.append(json.dumps(row, sort_keys=True))
    return sorted(out)


def errors(messages):
    out = []
    for m in messages:
        if (m.get("id"), str(m.get("number"))) == STOPPED:
            continue
        if m.get("type") in ("E", "A", "X"):
            out.append(m.get("text", "").strip())
    return sorted(set(out))


def compare(old, new, vol):
    diffs = []
    old_err, new_err = errors(old["messages"]), errors(new["messages"])
    if old_err != new_err:
        diffs.append({"what": "messages", "old": old_err, "new": new_err})
    for table in old["tables"]:
        a = normalise_rows(old["tables"][table], vol.get(table, set()))
        b = normalise_rows(new["tables"].get(table, []), vol.get(table, set()))
        if a != b:
            only_old = [json.loads(x) for x in a if x not in b]
            only_new = [json.loads(x) for x in b if x not in a]
            diffs.append({"what": f"rows of {table}", "old_only": only_old, "new_only": only_new})
    return diffs


def load_driver(tcode):
    path = os.path.join(ROOT, "runs", tcode, "port", "driver.py")
    spec = importlib.util.spec_from_file_location("driver", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


class RecordingClient(odata.Client):
    """Keeps every message the service sent during one case."""

    def __init__(self, *a, **kw):
        super().__init__(*a, **kw)
        self.seen = []

    def call(self, method, path, data=None, headers=None):
        r = super().call(method, path, data, headers)
        self.seen.extend(r.messages)
        return r

    def ui(self, type_, text):
        r = super().ui(type_, text)
        self.seen.append({"type": type_, "text": text, "from": "ui"})
        return r


def grade(tcode, cases, report_name="ZPP_RESTORE", oracle_report="ZPP_ORACLE_G", s=None, sealed_answers=None):
    s = s or sap.Sap()
    fields = table_fields(tcode)
    vol = volatile_fields(tcode)
    os.environ["ORACLE_REPORT"] = oracle_report
    t0 = time.time()
    old = oracle.replay(tcode, cases, s)
    t_old = time.time() - t0
    baseline = read_tables(s, fields)
    restore = abap.build(report_name, restore_report(baseline, fields))
    s.write_program(report_name, restore)
    service = load_json(os.path.join(ROOT, "runs", tcode, "port", "service.json"))
    driver = load_driver(tcode)
    results = []
    t1 = time.time()
    for case in cases:
        client = RecordingClient(service["root"], s)
        crash = None
        try:
            driver.run(client, case["steps"])
        except Exception as e:  # the driver failing is a result too
            crash = f"{type(e).__name__}: {e}"
        new = {"messages": client.seen, "tables": read_tables(s, fields)}
        s.run_program(report_name)
        diffs = compare(old[case["id"]], new, vol)
        if crash:
            diffs.insert(0, {"what": "driver crashed", "error": crash})
        drift = None
        if sealed_answers is not None:
            sealed_old = sealed_answers.get(case["id"])
            if sealed_old is None or compare(sealed_old, old[case["id"]], vol):
                drift = "the old transaction answered differently than when the cases were sealed"
        results.append({"id": case["id"], "intent": case.get("intent", ""), "pass": not diffs, "diffs": diffs,
                        "old_messages": errors(old[case["id"]]["messages"]), "new_messages": client.seen,
                        "drift": drift})
    t_new = time.time() - t1
    after = read_tables(s, fields)
    clean = all(normalise_rows(after[t], vol[t]) == normalise_rows(baseline[t], vol[t]) for t in fields)
    passed = sum(r["pass"] for r in results)
    return {"tcode": tcode, "cases": len(cases), "passed": passed, "failed": len(cases) - passed,
            "drift": sum(1 for r in results if r["drift"]), "tables_restored": clean,
            "seconds_old": round(t_old, 1), "seconds_new": round(t_new, 1), "results": results}


def main(argv):
    tcode = argv[0].upper()
    out = None
    if "--out" in argv:
        out = argv[argv.index("--out") + 1]
    sealed_answers = None
    if "--sealed" in argv:
        bundle_path = os.path.join(ROOT, "runs", tcode, "sealed", "bundle.json")
        with open(bundle_path, "rb") as f:
            raw = f.read()
        bundle = json.loads(raw)
        cases, sealed_answers = bundle["cases"], bundle["answers"]
        print(f"sealed bundle sha256 {hashlib.sha256(raw).hexdigest()}")
        report_name, oracle_report = "ZPP_RESTORE", "ZPP_ORACLE_G"
    else:
        cases = load_json(argv[1])
        report_name, oracle_report = "ZPP_RESTORE_P", "ZPP_ORACLE_P"
    report = grade(tcode, cases, report_name, oracle_report, sealed_answers=sealed_answers)
    text = json.dumps(report, indent=1, ensure_ascii=False)
    if out:
        with open(out, "w") as f:
            f.write(text)
    print(f"{report['passed']} of {report['cases']} cases behave the same; tables restored: "
          f"{report['tables_restored']}; drift: {report['drift']}")
    for r in report["results"]:
        if not r["pass"]:
            print(f"- {r['id']} {r['intent']}")
            for d in r["diffs"]:
                print(f"    {json.dumps(d, ensure_ascii=False)[:400]}")
    return 0 if report["failed"] == 0 else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

"""A small OData V4 client for the new service, handed to the port's driver by the grader.

The driver never sees credentials: it gets a Client and calls get, post, patch and delete with paths relative to the
service root. Every call returns a Response with the status, the JSON body and the messages the service sent (error
body and details, and the sap-messages header), each as {"type": "E"|"W"|"S"|"I", "text": ...}.
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(__file__))
import sap  # noqa: E402

SEVERITY = {1: "S", 2: "I", 3: "W", 4: "E"}


class Response:
    def __init__(self, status, body, messages):
        self.status, self.body, self.messages = status, body, messages

    @property
    def ok(self):
        return 200 <= self.status < 300

    def __repr__(self):
        return f"Response({self.status}, messages={self.messages})"


class Client:
    def __init__(self, service_root, s=None):
        self.s = s or sap.Sap()
        self.root = service_root.rstrip("/") + "/"
        self.csrf = None

    def _messages(self, headers, body):
        out = []
        err = body.get("error") if isinstance(body, dict) else None
        if err:
            details = err.get("details") or []
            if not details:
                out.append({"type": "E", "text": err.get("message", "")})
            for d in details:
                out.append({"type": SEVERITY.get(d.get("@Common.numericSeverity"), "E"), "text": d.get("message", "")})
            if details and err.get("message") and err["message"] not in [d.get("message") for d in details]:
                out.insert(0, {"type": "E", "text": err["message"]})
        raw = headers.get("sap-messages") if headers else None
        if raw:
            try:
                for m in json.loads(raw):
                    out.append({"type": SEVERITY.get(m.get("numericSeverity"), "I"), "text": m.get("message", "")})
            except ValueError:
                pass
        return out

    def call(self, method, path, data=None, headers=None):
        if method != "GET" and not self.csrf:
            self._fetch_csrf()
        url = self.root + path.lstrip("/")
        hdrs = {"Accept": "application/json", "Authorization": self.s.auth}
        if self.csrf:
            hdrs["X-CSRF-Token"] = self.csrf
        body = None
        if data is not None:
            body = json.dumps(data).encode()
            hdrs["Content-Type"] = "application/json"
        hdrs.update(headers or {})
        import urllib.request
        import urllib.error
        req = urllib.request.Request(url + ("&" if "?" in url else "?") + "sap-client=" + self.s.client,
                                     data=body, method=method, headers=hdrs)
        try:
            with self.s.opener.open(req, timeout=120) as resp:
                status, h, text = resp.status, resp.headers, resp.read().decode("utf-8", "replace")
        except urllib.error.HTTPError as e:
            status, h, text = e.code, e.headers, e.read().decode("utf-8", "replace")
            if status == 403 and "csrf" in (e.headers.get("x-csrf-token", "") or "").lower():
                self.csrf = None
                self._fetch_csrf()
                return self.call(method, path, data, headers)
        try:
            parsed = json.loads(text) if text.strip() else {}
        except ValueError:
            parsed = {"raw": text[:2000]}
        return Response(status, parsed, self._messages(h, parsed))

    def _fetch_csrf(self):
        import urllib.request
        req = urllib.request.Request(self.root + "?sap-client=" + self.s.client,
                                     headers={"X-CSRF-Token": "Fetch", "Authorization": self.s.auth,
                                              "Accept": "application/json"})
        with self.s.opener.open(req, timeout=60) as resp:
            self.csrf = resp.headers.get("x-csrf-token")

    def ui(self, type_, text):
        """Record a message the app's UI shows before calling the service (input format only, never a rule)."""
        self.ui_messages = getattr(self, "ui_messages", []) + [{"type": type_, "text": text, "from": "ui"}]
        return Response(0, {}, [{"type": type_, "text": text}])

    def get(self, path, **kw):
        return self.call("GET", path, **kw)

    def post(self, path, data=None, **kw):
        return self.call("POST", path, data if data is not None else {}, **kw)

    def patch(self, path, data, **kw):
        return self.call("PATCH", path, data, **kw)

    def delete(self, path, **kw):
        return self.call("DELETE", path, **kw)

"""Talk to an SAP system through its ADT REST interface.

Credentials come from an env file with A4H_USER, A4H_PASSWORD and A4H_CLIENT (default ~/.config/evolve/a4h.env, or
SAP_ENV). The base URL is SAP_URL, by default a local SSH tunnel. One Sap object keeps one set of cookies, so it uses
one security session on the server instead of one per request.
"""
import base64
import http.cookiejar
import os
import re
import urllib.error
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET

DEFAULT_ENV = "~/.config/evolve/a4h.env"
DEFAULT_URL = "http://127.0.0.1:15000"
PACKAGE = "$TMP"


class SapError(Exception):
    pass


def load_env(path):
    values = {}
    with open(os.path.expanduser(path)) as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                key, value = line.split("=", 1)
                values[key.strip()] = value.strip().strip('"').strip("'")
    return values


class Sap:
    def __init__(self, env=None, url=None):
        values = load_env(env or os.environ.get("SAP_ENV", DEFAULT_ENV))
        self.user = values["A4H_USER"]
        self.client = values["A4H_CLIENT"]
        token = base64.b64encode(f"{self.user}:{values['A4H_PASSWORD']}".encode()).decode()
        self.auth = "Basic " + token
        self.url = (url or os.environ.get("SAP_URL", DEFAULT_URL)).rstrip("/")
        self.jar = http.cookiejar.CookieJar()
        self.opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(self.jar))
        self.csrf = None

    # -- plumbing ---------------------------------------------------------------------------------------------------

    def request(self, method, path, body=None, content_type=None, accept="*/*", stateful=False, retry=True):
        url = self.url + path + ("&" if "?" in path else "?") + "sap-client=" + self.client
        headers = {"Authorization": self.auth, "Accept": accept, "X-CSRF-Token": self.csrf or "Fetch"}
        if content_type:
            headers["Content-Type"] = content_type
        if stateful:
            headers["X-sap-adt-sessiontype"] = "stateful"
        data = body.encode("utf-8") if isinstance(body, str) else body
        req = urllib.request.Request(url, data=data, method=method, headers=headers)
        try:
            with self.opener.open(req, timeout=300) as resp:
                self.csrf = resp.headers.get("x-csrf-token", self.csrf)
                return resp.status, resp.headers, resp.read().decode("utf-8", "replace")
        except urllib.error.HTTPError as e:
            text = e.read().decode("utf-8", "replace")
            if e.code == 403 and retry and "csrf" in (e.headers.get("x-csrf-token", "") + text).lower():
                self.csrf = None
                self.fetch_csrf()
                return self.request(method, path, body, content_type, accept, stateful, retry=False)
            raise SapError(f"{method} {path}: HTTP {e.code}: {short(text)}") from None

    def fetch_csrf(self):
        self.request("GET", "/sap/bc/adt/discovery", accept="application/atomsvc+xml")

    def post(self, path, body="", **kw):
        if not self.csrf:
            self.fetch_csrf()
        return self.request("POST", path, body, **kw)

    # -- reading ----------------------------------------------------------------------------------------------------

    def sql(self, query, rows=5000):
        """Run an Open SQL SELECT through the data preview and return a list of dicts (values as strings)."""
        _, _, text = self.post(f"/sap/bc/adt/datapreview/freestyle?rowNumber={rows}", query,
                               content_type="text/plain", accept="application/xml, application/vnd.sap.adt.datapreview.table.v1+xml")
        root = ET.fromstring(text)
        columns = []
        for col in root.iter():
            if local(col.tag) != "columns":
                continue
            name, values = None, []
            for child in col:
                if local(child.tag) == "metadata":
                    name = attr(child, "name")
                elif local(child.tag) == "dataSet":
                    values = [(d.text or "") for d in child]
            columns.append((name, values))
        count = max((len(v) for _, v in columns), default=0)
        return [{name: values[i].rstrip() for name, values in columns} for i in range(count)]

    def source(self, uri):
        _, _, text = self.request("GET", uri, accept="text/plain")
        return text

    def program_source(self, name):
        return self.source(f"/sap/bc/adt/programs/programs/{q(name)}/source/main")

    def include_source(self, name):
        return self.source(f"/sap/bc/adt/programs/includes/{q(name)}/source/main")

    # -- writing and running ABAP -----------------------------------------------------------------------------------

    def write_program(self, name, source, description="Proof Port helper"):
        """Create the report if needed, replace its source and activate it. Local objects only ($TMP)."""
        uri = f"/sap/bc/adt/programs/programs/{q(name)}"
        if not self.exists(uri):
            body = (
                '<?xml version="1.0" encoding="UTF-8"?>'
                '<program:abapProgram xmlns:program="http://www.sap.com/adt/programs/programs" '
                'xmlns:adtcore="http://www.sap.com/adt/core" '
                f'adtcore:description="{description}" adtcore:name="{name.upper()}" adtcore:type="PROG/P" '
                f'adtcore:responsible="{self.user}">'
                f'<adtcore:packageRef adtcore:name="{PACKAGE}"/></program:abapProgram>'
            )
            self.post("/sap/bc/adt/programs/programs", body,
                      content_type="application/vnd.sap.adt.programs.programs.v2+xml")
        _, _, text = self.post(f"{uri}?_action=LOCK&accessMode=MODIFY", stateful=True,
                               accept="application/vnd.sap.as+xml;charset=UTF-8;dataname=com.sap.adt.lock.result")
        handle = urllib.parse.quote(re.search(r"<LOCK_HANDLE>(.*?)</LOCK_HANDLE>", text).group(1), safe="")
        try:
            self.request("PUT", f"{uri}/source/main?lockHandle={handle}", source,
                         content_type="text/plain; charset=utf-8", stateful=True)
        finally:
            try:
                self.post(f"{uri}?_action=UNLOCK&lockHandle={handle}", stateful=True)
            except SapError as e:
                print(f"warning: unlock of {name} failed: {e}")
        self.activate(uri, name)

    def activate(self, uri, name):
        body = (
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<adtcore:objectReferences xmlns:adtcore="http://www.sap.com/adt/core">'
            f'<adtcore:objectReference adtcore:uri="{uri}" adtcore:name="{name.upper()}"/>'
            '</adtcore:objectReferences>'
        )
        _, _, text = self.post("/sap/bc/adt/activation?method=activate&preauditRequested=true", body,
                               content_type="application/xml")
        errors = re.findall(r'<msg[^>]*type="E"[^>]*>.*?<txt>(.*?)</txt>', text, re.S)
        if errors:
            raise SapError(f"activating {name}: " + " | ".join(errors))

    def exists(self, uri):
        try:
            self.request("GET", uri, accept="application/vnd.sap.adt.programs.programs.v2+xml, application/xml")
            return True
        except SapError as e:
            if "HTTP 404" in str(e):
                return False
            raise

    def run_program(self, name):
        """Run a report without a selection screen and return its list output as text."""
        _, _, text = self.post(f"/sap/bc/adt/programs/programrun/{q(name)}", accept="text/plain")
        return text

    def run_abap(self, source, name="ZPP_RUN"):
        self.write_program(name, source)
        return self.run_program(name)


def local(tag):
    return tag.rsplit("}", 1)[-1]


def attr(el, name):
    for key, value in el.attrib.items():
        if local(key) == name:
            return value
    return None


def q(name):
    return urllib.parse.quote(name.lower(), safe="")


def short(text, n=400):
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", text).strip()[:n]

