import json, sys
out = sys.argv[1]
casesf = sys.argv[2]
d = json.load(open(out))
cases = {c["id"]: c for c in json.load(open(casesf))}
base = {"C100": 5000.0, "C200": 1000.0, "C300": 50000.0, "C400": 2000.0}
blk = {"C100": "", "C200": "X", "C300": "", "C400": ""}
for k in cases:
    v = d.get(k)
    print("=" * 72)
    if v is None:
        print(k, "NO RESULT")
        continue
    print(k, cases[k].get("intent", ""), "| subrc", v["subrc"])
    for m in v["messages"]:
        print("   MSG %s %s/%s %r  [%s]" % (m["type"], m["id"], m["number"], m["text"], m["screen"]))
    la = v["last"]
    if la.get("type"):
        print("   last: %s %s/%s %r" % (la["type"], la["id"], la["number"], la.get("text", "")))
    for row in v["tables"]["ZCR_CUSTOMER"]:
        kn = row["KUNNR"]
        if float(row.get("CREDIT_LIMIT") or 0) != base[kn] or (row.get("BLOCKED") or "") != blk[kn]:
            print("   CUST", kn, "limit", row.get("CREDIT_LIMIT"), "blocked", repr(row.get("BLOCKED")))
    for row in v["tables"]["ZCR_CHANGELOG"]:
        print("   LOG", {a: b for a, b in row.items() if a != "MANDT"})

