import json
d=json.load(open('runs/ZCRED/port/probe1_out.json'))
cases={c['id']:c for c in json.load(open('runs/ZCRED/port/probe1.json'))}
base={'C100':'5000.00','C200':'1000.00','C300':'50000.00','C400':'2000.00'}
for k,v in d.items():
    print('='*70)
    print(k, cases[k]['intent'], 'subrc',v['subrc'])
    for m in v['messages']:
        print('   MSG', m['type'], m['id'], m['number'], repr(m['text']), m['screen'])
    print('   last:', v['last'])
    for row in v['tables']['ZCR_CUSTOMER']:
        if str(row.get('CREDIT_LIMIT'))!=base[row['KUNNR']].rstrip('0').rstrip('.') and float(row.get('CREDIT_LIMIT',0))!=float(base[row['KUNNR']]):
            print('   CUST CHANGED', row)
        elif row.get('BLOCKED')!=('X' if row['KUNNR']=='C200' else ''):
            print('   CUST BLOCKFLAG', row)
    for row in v['tables']['ZCR_CHANGELOG']:
        print('   LOG', {kk:vv for kk,vv in row.items() if kk!='MANDT'})
EOF
